<?php
$page_title = 'Purchase Receiving Details';
require_once __DIR__ . '/../../includes/header.php';
/** @var mysqli $conn */
$conn = getDatabaseConnection();

$permissions = require __DIR__ . '/permissions.php';
$businessId = (int)($_SESSION['active_business_id'] ?? 0);
$membershipId = (int)($_SESSION['membership_id'] ?? 0);
requirePermission($conn, $membershipId, $businessId, $permissions['view']);
$canReceive = hasPermission($conn, $membershipId, $businessId, $permissions['receive']);
$config = getBusinessInventoryConfig($conn, $businessId);
$localNow = new DateTimeImmutable('now', new DateTimeZone($config['timezone']));
$csrfToken = generateCsrfToken();
$role = getPreviewRole();
$roleQuery = $role ? '&role=' . rawurlencode($role) : '';
$roleOnlyQuery = $role ? '?role=' . rawurlencode($role) : '';
$purchaseId = (int)($_GET['id'] ?? 0);

$returnParams=[];foreach(['status','search','page'] as $key){if(isset($_GET[$key])&&trim((string)$_GET[$key])!=='')$returnParams[$key]=(string)$_GET[$key];}if($role)$returnParams['role']=$role;
$queueUrl='index'.($returnParams?'?'.http_build_query($returnParams):'');

$purchaseStmt=mysqli_prepare($conn,"SELECT p.*,s.name supplier_name,s.supplier_code,l.name location_name,l.code location_code,COALESCE(SUM(pi.ordered_quantity*pi.unit_cost),0) ordered_value,COALESCE(SUM(pi.received_quantity*pi.unit_cost),0) received_value,COALESCE(SUM((pi.ordered_quantity-pi.received_quantity)*pi.unit_cost),0) remaining_value FROM purchases p JOIN suppliers s ON s.id=p.supplier_id AND s.business_id=p.business_id JOIN business_locations l ON l.id=p.location_id AND l.business_id=p.business_id JOIN purchase_items pi ON pi.purchase_id=p.id AND pi.business_id=p.business_id WHERE p.id=? AND p.business_id=? AND p.status IN ('ORDERED','PARTIALLY_RECEIVED','RECEIVED') GROUP BY p.id,s.name,s.supplier_code,l.name,l.code LIMIT 1");
mysqli_stmt_bind_param($purchaseStmt,'ii',$purchaseId,$businessId);mysqli_stmt_execute($purchaseStmt);$purchase=mysqli_fetch_assoc(mysqli_stmt_get_result($purchaseStmt));
if(!$purchase){http_response_code(404);?><main class="receipt-page"><section class="card receipt-missing"><h1>Receiving record not found</h1><p>This purchase is unavailable or has not been submitted for receiving.</p><a class="receipt-button receipt-button-primary" href="<?php echo e($queueUrl);?>">Back to Receiving Queue</a></section></main><?php require_once __DIR__.'/../../includes/footer.php';exit;}

$lines=[];$lineStmt=mysqli_prepare($conn,'SELECT pi.id,pi.purchase_quantity,pi.conversion_factor_to_base,pi.ordered_quantity,pi.received_quantity,pi.unit_cost,pi.purchase_unit_cost,pi.unit_selling_price,pi.line_total,pi.expiry_date expires_at,pr.name product_name,pr.sku,pr.uom,u.code purchase_uom FROM purchase_items pi JOIN products pr ON pr.id=pi.product_id AND pr.business_id=pi.business_id JOIN units_of_measure u ON u.id=pi.purchase_uom_id WHERE pi.purchase_id=? AND pi.business_id=? ORDER BY pi.id');mysqli_stmt_bind_param($lineStmt,'ii',$purchaseId,$businessId);mysqli_stmt_execute($lineStmt);$result=mysqli_stmt_get_result($lineStmt);while($row=mysqli_fetch_assoc($result))$lines[]=$row;
$businessStmt=mysqli_prepare($conn,'SELECT currency_code FROM businesses WHERE id=? LIMIT 1');mysqli_stmt_bind_param($businessStmt,'i',$businessId);mysqli_stmt_execute($businessStmt);$currency=mysqli_fetch_assoc(mysqli_stmt_get_result($businessStmt))['currency_code']??'RWF';
$orderedValue=(float)$purchase['ordered_value'];$receivedValue=(float)$purchase['received_value'];$remainingValue=(float)$purchase['remaining_value'];$progress=$orderedValue>0?min(100,($receivedValue/$orderedValue)*100):100;$completed=$purchase['status']==='RECEIVED';$isDirectPurchase=($purchase['purchase_type']??'PURCHASE_ORDER')==='DIRECT';$purchaseTypeLabel=$isDirectPurchase?'Direct Purchase':'Purchase Order';
?>

<main class="receipt-page">
  <nav class="receipt-breadcrumb"><a href="<?php echo e($queueUrl);?>">Receiving Queue</a><span>/</span><span><?php echo e($purchase['purchase_number']);?></span></nav>
  <header class="receipt-header"><div><span><?php echo e($purchaseTypeLabel); ?> receiving</span><h1><?php echo $completed?'Receiving Details':($isDirectPurchase?'Receive Direct Purchase':'Receive Purchase Order');?></h1><p><?php echo e($purchase['purchase_number'].' · '.$purchase['supplier_name'].' · '.$purchase['location_name']);?></p></div><div class="receipt-header-actions"><span class="status-pill <?php echo $completed?'pill-green':'pill-amber';?>"><?php echo $completed?'Fully Received':($purchase['status']==='PARTIALLY_RECEIVED'?'Partially Received':'Waiting for Receipt');?></span><a class="receipt-button receipt-button-secondary" href="<?php echo e($queueUrl);?>">Back to Receiving Queue</a><a class="receipt-button receipt-button-secondary" href="../purchase/view?id=<?php echo $purchaseId.$roleQuery;?>">View Purchase Details</a></div></header>
  <section class="receipt-summary"><article><span>Ordered Value</span><strong><?php echo formatCurrency($orderedValue,$currency);?></strong><small><?php echo count($lines);?> product line(s)</small></article><article><span>Received Value</span><strong><?php echo formatCurrency($receivedValue,$currency);?></strong><small><?php echo e(number_format($progress,1));?>% received</small></article><article><span>Remaining Value</span><strong><?php echo formatCurrency($remainingValue,$currency);?></strong><small>Still expected</small></article><article><span>Supplier Invoice</span><strong><?php echo e($purchase['supplier_invoice_number']?:'Not recorded');?></strong><small><?php echo $purchase['received_at']?e(formatDate($purchase['received_at'],$config['timezone'],'d M Y, H:i')):'Receipt not completed';?></small></article></section>

  <?php if(!$completed&&$canReceive):?><form action="../purchase/backend<?php echo e($roleOnlyQuery);?>" method="POST" id="receivePurchaseForm"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken);?>"><input type="hidden" name="idempotency_key" value="<?php echo e(createIdempotencyToken());?>"><input type="hidden" name="action" value="receive_po"><input type="hidden" name="return_to" value="receiving_view:<?php echo $purchaseId;?>"><input type="hidden" name="purchase_id" value="<?php echo $purchaseId;?>"><?php endif;?>
  <div class="receipt-layout">
    <section class="receipt-card receipt-lines-card"><div class="receipt-section-head"><div><h2>Products to Receive</h2><p>Enter receipts in the purchase form originally saved on each line.</p></div><span><?php echo count($lines);?> lines</span></div><div class="receipt-progress-large"><div><span style="width:<?php echo e(number_format($progress,2,'.',''));?>%"></span></div><small><?php echo e(number_format($progress,1));?>% of purchase value received</small></div><div class="receipt-table-scroll"><table class="data-table receipt-lines"><thead><tr><th>Product</th><th>Order Progress</th><th>Values</th><?php if(!$completed&&$canReceive):?><th>Quantity to Receive</th><?php endif;?></tr></thead><tbody><?php foreach($lines as $line):$remaining=max(0,(float)$line['ordered_quantity']-(float)$line['received_quantity']);$factor=(float)$line['conversion_factor_to_base'];$remainingEntered=convertBaseQuantityToTransaction($remaining,$factor);?><tr><td><strong><?php echo e($line['product_name']);?></strong><small>SKU <?php echo e($line['sku']);?><?php echo $line['expires_at']?' · Expires '.e(date('d M Y',strtotime($line['expires_at']))):'';?></small></td><td><small>Ordered <b><?php echo formatInventoryDecimal($line['purchase_quantity']).' '.e($line['purchase_uom']);?></b></small><small class="receipt-positive">Already received <b><?php echo formatInventoryDecimal(convertBaseQuantityToTransaction($line['received_quantity'],$factor)).' '.e($line['purchase_uom']);?></b></small><small class="receipt-warning">Remaining <b><?php echo formatInventoryDecimal($remainingEntered).' '.e($line['purchase_uom']);?></b></small><small><?php echo formatInventoryDecimal($line['ordered_quantity']).' '.e($line['uom']);?> canonical</small></td><td><small>Received <b><?php echo formatCurrency((float)$line['received_quantity']*(float)$line['unit_cost'],$currency);?></b></small><small>Remaining <b><?php echo formatCurrency($remaining*(float)$line['unit_cost'],$currency);?></b></small></td><?php if(!$completed&&$canReceive):?><td><input type="hidden" name="item_ids[]" value="<?php echo (int)$line['id'];?>"><input class="receipt-quantity" type="number" name="received_quantities[]" min="0" max="<?php echo e(number_format($remainingEntered,4,'.',''));?>" step=".0001" value="0" data-remaining="<?php echo e(number_format($remainingEntered,4,'.',''));?>" <?php echo $remaining<=0?'readonly':'';?> aria-label="Quantity to receive for <?php echo e($line['product_name']);?>"><small><?php echo e($line['purchase_uom']);?> available to receive</small></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></section>
    <aside class="receipt-sidebar">
      <section class="receipt-card"><div class="receipt-section-head"><div><h2>Receiving Information</h2><p>How this stock receipt should be posted.</p></div></div><?php if(!$completed&&$canReceive):?><div class="receipt-fields"><label>Receipt Completion<select name="receipt_status" id="receiptStatus"><option value="PENDING">Partial Receipt</option><option value="RECEIVED">Receive All and Complete</option></select><small>Receive All automatically fills every outstanding quantity.</small></label><label>Supplier Invoice / Delivery Note<input name="supplier_invoice_number" value="<?php echo e($purchase['supplier_invoice_number']);?>" placeholder="Invoice or delivery note number"></label><label>Received Date and Time<input type="datetime-local" name="received_at" value="<?php echo e($localNow->format('Y-m-d\TH:i'));?>" required></label></div><?php else:?><dl class="receipt-info-list"><div><dt>Order date</dt><dd><?php echo e(formatDate($purchase['purchase_date'],$config['timezone'],'d M Y, H:i'));?></dd></div><div><dt>Received at</dt><dd><?php echo $purchase['received_at']?e(formatDate($purchase['received_at'],$config['timezone'],'d M Y, H:i')):'Not completed';?></dd></div><div><dt>Supplier</dt><dd><?php echo e($purchase['supplier_name']);?></dd></div><div><dt>Delivery location</dt><dd><?php echo e($purchase['location_name'].' ('.$purchase['location_code'].')');?></dd></div></dl><?php endif;?></section>
      <?php if(!$completed&&!$canReceive):?><section class="receipt-card receipt-permission-note">You can review this receiving record, but you do not have permission to post stock receipts.</section><?php endif;?>
      <?php if(!$completed&&$canReceive):?><section class="receipt-card receipt-help"><h2>Before Posting</h2><ul><li>Count the physical stock received.</li><li>Enter only quantities delivered now.</li><li>Choose “Receive All and Complete” only when all remaining stock arrived.</li></ul></section><?php endif;?>
    </aside>
  </div>
  <?php if(!$completed&&$canReceive):?><footer class="receipt-actions-bar"><a class="receipt-button receipt-button-secondary" href="<?php echo e($queueUrl);?>">Cancel and Return</a><button class="receipt-button receipt-button-primary" id="postReceiptButton">Post Partial Receipt</button></footer></form><?php endif;?>
</main>

<style>
.receipt-page{max-width:1480px;margin:0 auto}.receipt-breadcrumb{display:flex;gap:7px;margin-bottom:10px;color:var(--text3);font-size:9.5px}.receipt-breadcrumb a{color:var(--green);text-decoration:none}.receipt-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:17px 19px;border:1px solid var(--border);border-radius:12px;background:var(--card)}.receipt-header>div>span{color:var(--text3);font-size:8px;text-transform:uppercase}.receipt-header h1{margin:5px 0 0;color:var(--text);font-size:20px}.receipt-header p{margin:5px 0 0;color:var(--text3);font-size:10px}.receipt-header-actions{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.receipt-button{display:inline-flex;align-items:center;justify-content:center;min-height:36px;padding:8px 12px;border:1px solid transparent;border-radius:8px;font:inherit;font-size:9.5px;font-weight:650;text-decoration:none;cursor:pointer}.receipt-button-primary{background:var(--green);border-color:var(--green);color:#fff}.receipt-button-secondary{background:var(--card);border-color:var(--border);color:var(--text2)}.receipt-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:11px 0}.receipt-summary article{padding:13px 15px;border:1px solid var(--border);border-radius:10px;background:var(--card)}.receipt-summary span,.receipt-summary small{display:block;color:var(--text3);font-size:8.5px}.receipt-summary span{text-transform:uppercase}.receipt-summary strong{display:block;margin:6px 0 3px;color:var(--text);font-size:14px;overflow-wrap:anywhere}.receipt-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:11px;align-items:start}.receipt-sidebar{display:flex;flex-direction:column;gap:11px}.receipt-card{border:1px solid var(--border);border-radius:11px;background:var(--card);overflow:hidden}.receipt-section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 15px;border-bottom:1px solid var(--border)}.receipt-section-head h2,.receipt-help h2{margin:0;color:var(--text);font-size:11px}.receipt-section-head p{margin:3px 0 0;color:var(--text3);font-size:8.5px}.receipt-section-head>span{padding:4px 7px;border-radius:99px;background:var(--bg);color:var(--text3);font-size:8px}.receipt-progress-large{display:flex;align-items:center;gap:10px;padding:9px 15px;background:var(--bg)}.receipt-progress-large>div{width:200px;height:6px;border-radius:99px;background:var(--card);overflow:hidden}.receipt-progress-large>div span{display:block;height:100%;background:var(--green)}.receipt-progress-large small{color:var(--text3);font-size:8.5px}.receipt-table-scroll{max-height:60vh;overflow:auto}.receipt-lines{min-width:760px}.receipt-lines th{position:sticky;top:0;background:var(--card);z-index:2}.receipt-lines td{vertical-align:middle}.receipt-lines td strong,.receipt-lines td small{display:block}.receipt-lines td small{margin-top:4px;color:var(--text3);font-size:8.5px}.receipt-lines td small b{display:inline;color:var(--text2)}.receipt-positive{color:var(--green)!important}.receipt-warning{color:var(--orange)!important}.receipt-quantity{width:140px;min-height:38px;padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--text);font:inherit}.receipt-fields{display:grid;gap:11px;padding:14px}.receipt-fields label{display:flex;flex-direction:column;gap:6px;color:var(--text2);font-size:9px;font-weight:650}.receipt-fields input,.receipt-fields select{width:100%;min-height:39px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--text);font:inherit}.receipt-fields small{color:var(--text3);font-size:8px;font-weight:400}.receipt-info-list{margin:0;padding:5px 14px}.receipt-info-list>div{display:grid;grid-template-columns:100px 1fr;gap:10px;padding:9px 0;border-bottom:1px solid var(--border)}.receipt-info-list>div:last-child{border-bottom:0}.receipt-info-list dt{color:var(--text3);font-size:8.5px}.receipt-info-list dd{margin:0;color:var(--text2);font-size:9px;text-align:right}.receipt-help{padding:14px}.receipt-help ul{display:grid;gap:7px;margin:10px 0 0;padding-left:17px;color:var(--text2);font-size:8.5px}.receipt-permission-note{padding:13px;color:var(--text3);font-size:9px}.receipt-actions-bar{display:flex;justify-content:flex-end;gap:8px;margin-top:11px;padding:12px 14px;border:1px solid var(--border);border-radius:11px;background:var(--card);position:sticky;bottom:8px}.receipt-missing{max-width:620px;margin:70px auto;padding:28px;text-align:center}.receipt-missing p{color:var(--text3)}
@media(max-width:980px){.receipt-layout{grid-template-columns:1fr}.receipt-sidebar{display:grid;grid-template-columns:1fr 1fr}.receipt-summary{grid-template-columns:1fr 1fr}}
@media(max-width:680px){.receipt-header{align-items:flex-start;flex-direction:column}.receipt-header-actions{justify-content:flex-start}.receipt-sidebar,.receipt-summary{grid-template-columns:1fr}.receipt-actions-bar{align-items:stretch;flex-direction:column}.receipt-button{width:100%}}
</style>

<?php if(!$completed&&$canReceive):?><script>
const receiptStatus=document.getElementById('receiptStatus');
function syncReceiptForm(){const complete=receiptStatus.value==='RECEIVED';document.querySelectorAll('.receipt-quantity').forEach(input=>{if(complete)input.value=input.dataset.remaining;});document.getElementById('postReceiptButton').textContent=complete?'Receive All and Complete Purchase':'Post Partial Receipt';}
receiptStatus.addEventListener('change',syncReceiptForm);document.getElementById('receivePurchaseForm').addEventListener('submit',function(){const button=document.getElementById('postReceiptButton');button.disabled=true;button.textContent='Posting Receipt...';});
</script><?php endif;?>
<?php require_once __DIR__ . '/../../includes/footer.php'; ?>
